<?= view('layout/header',['title'=>'Record Sale']) ?><div class="card"><h1>Record Sale</h1><form method="post"><label>Product</label><select name="product_id" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?> — <?= number_format($p['price'],2) ?> (<?= $p['stock_quantity'] ?> available)</option><?php endforeach ?></select><label>Customer (optional)</label><select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= esc($c['full_name']) ?></option><?php endforeach ?></select><label>Quantity</label><input type="number" name="quantity" min="1" required><button>Record sale</button> <a href="<?= site_url('sales') ?>">Cancel</a></form></div><?= view('layout/footer') ?>
